parameters.jsCode:
// One Buyer Interest opportunity per buyer WHO ACTUALLY RECEIVED the teaser.
// This is the durable buyer<->deal association: open the Buyer Interest
// pipeline, search the address, and every buyer tied to that deal is listed
// with the stage they reached. Contact fields can't express this - a buyer
// belongs to many deals over time.
const pipes = ($input.first().json.pipelines) || [];
const bi = pipes.find(p => (p.name || '').toLowerCase().indexOf('buyer interest') !== -1);

const tally = $('Tally Sends').first().json;
const recips = $('Build Recipient List').all();

if (!bi || !bi.stages || !bi.stages.length) {
  return [{ json: { _skip: true, reason: 'Buyer Interest pipeline not found' } }];
}

// Prefer a stage that honestly means "we texted them"; otherwise fall back to
// the first stage. Renaming/adding a stage in GHL needs no code change.
const wanted = ['reached out', 'texted', 'sent', 'blasted', 'contacted'];
let stage = bi.stages.find(s => wanted.indexOf((s.name || '').toLowerCase()) !== -1);
if (!stage) stage = bi.stages[0];

const sentNames = new Set((tally.sent_rows || []).map(r => r.name));
const out = [];
for (const r of recips) {
  const b = r.json;
  if (!b || !b.contactId) continue;
  if (!sentNames.has(b.name)) continue;   // only buyers who actually got it
  out.push({ json: {
    opp: {
      pipelineId: bi.id,
      locationId: 'ib5jEnyqqq06FIEqlVGs',
      name: (tally.address || 'Deal') + ' — ' + b.name,
      pipelineStageId: stage.id,
      status: 'open',
      contactId: b.contactId
    },
    _stageName: stage.name
  } });
}

if (!out.length) return [{ json: { _skip: true, reason: 'nothing sent' } }];
return out;
